 if(isset($_POST['import'])){if(empty($_FILES['csv']['tmp_name'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('فایل CSV انتخاب نشده است.');$fh=fopen($_FILES['csv']['tmp_name'],'rb');$header=fgetcsv($fh);if(!$header)throw new RuntimeException('فایل خالی است.');$header=array_map(fn($v)=>trim((string)$v),$header);$required=['full_name'];if(!in_array('full_name',$header,true)&&!in_array('نام و نام خانوادگی',$header,true))throw new RuntimeException('ستون full_name یا نام و نام خانوادگی الزامی است.');$db=db();$db->beginTransaction();$ok=0;$fail=0;$errors=[];while(($row=fgetcsv($fh))!==false){$r=[];foreach($header as $i=>$h)$r[$h]=trim((string)($row[$i]??''));$name=$r['full_name']??$r['نام و نام خانوادگی']??'';if($name===''){++$fail;continue;}$code=$r['personnel_code']??$r['کد پرسنلی']??null;$national=$r['national_id']??$r['کد ملی']??null;$dept=$r['department']??$r['اداره']??$r['دانشکده']??null;$q=$db->prepare('SELECT id FROM personnel WHERE personnel_code=? AND personnel_code IS NOT NULL AND personnel_code<>""');$q->execute([$code]);$id=$q->fetchColumn();if($id){$q=$db->prepare('UPDATE personnel SET national_id=?,full_name=?,department=?,position=?,extra=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$q->execute([$national,$name,$dept,$r['position']??$r['سمت']??null,json_encode($r,JSON_UNESCAPED_UNICODE),$id]);}else{$q=$db->prepare('INSERT INTO personnel(personnel_code,national_id,full_name,department,position,extra) VALUES(?,?,?,?,?,?)');$q->execute([$code,$national,$name,$dept,$r['position']??$r['سمت']??null,json_encode($r,JSON_UNESCAPED_UNICODE)]);}$ok++;}$db->commit();fclose($fh);audit('personnel_import','personnel',null,['file'=>basename($_FILES['csv']['name']),'imported'=>$ok,'failed'=>$fail]);$message="ورود اطلاعات انجام شد: {$ok} رکورد.";}else{$name=trim((string)($_POST['full_name']??''));if($name==='')throw new RuntimeException('نام و نام خانوادگی الزامی است.');$q=db()->prepare('INSERT INTO personnel(personnel_code,national_id,full_name,depar